UPDATE `quest_template_locale` SET `QuestDescription` = 'Эй, $gприятель:подруга;! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! $b$bУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! $b$bДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и $gсам:сама; сможешь там отдохнуть, если захочешь. По крайней мере, ты $gдолжен:должна; туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.' WHERE `ID` = 8 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Эй, $gприятель:подруга;! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! $b$bУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! $b$bДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и $gсам:сама; сможешь там отдохнуть, если захочешь. По крайней мере, ты $gдолжен:должна; туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.' AS BINARY)));
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... $b$bЧто? Слишком фальшивлю? Не $gкупился:купилась;?$b$bНу так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! $b$bВозвращайся, когда будет что потратить... бродяга. $b$bИ вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости.' WHERE `ID` = 8 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... $b$bЧто? Слишком фальшивлю? Не $gкупился:купилась;?$b$bНу так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! $b$bВозвращайся, когда будет что потратить... бродяга. $b$bИ вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости.' AS BINARY)));
