UPDATE `quest_template_locale` SET `QuestDescription` = 'Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $n, и пусть весь Западный Край узнает о силе Света.$b$bЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $gубил:убила; 15 погромщиков и 15 мошенников из Братства Справедливости.' WHERE `ID` = 13 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $n, и пусть весь Западный Край узнает о силе Света.$b$bЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $gубил:убила; 15 погромщиков и 15 мошенников из Братства Справедливости.' AS BINARY)));
