UPDATE `quest_template_locale` SET `QuestDescription` = 'Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них.\r\n\r\nНаш успех на Бастионе зависит от битвы на один фронт: мы не можем допустить атаки с тыла и уж конечно не можем лишить наших защитников линии поставки припасов.\r\n\r\nПомоги Бастиону. Отправляйся на восток и убей любого приспешника Плети, которого встретишь. Особое внимание обрати на усадьбу Балнира на востоке – там настоящее гнездо Плети.', `QuestCompletionLog` = '' WHERE `ID` = 356 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них.\r\n\r\nНаш успех на Бастионе зависит от битвы на один фронт: мы не можем допустить атаки с тыла и уж конечно не можем лишить наших защитников линии поставки припасов.\r\n\r\nПомоги Бастиону. Отправляйся на восток и убей любого приспешника Плети, которого встретишь. Особое внимание обрати на усадьбу Балнира на востоке – там настоящее гнездо Плети.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
