UPDATE `quest_template_locale` SET `QuestDescription` = 'Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими.$B$BВариматрас, подручный Темной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стерто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден.$B$BПомоги нам истребить их, |3-6($c). Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Темной Госпоже.' WHERE `ID` = 374 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими.$B$BВариматрас, подручный Темной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стерто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден.$B$BПомоги нам истребить их, |3-6($c). Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Темной Госпоже.' AS BINARY)));
