UPDATE `quest_template_locale` SET `QuestDescription` = 'Так холодно... Чума Нежити расползается по моим венам, как клубок ледяных змей, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне 5 шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, $n, чтобы я могла и дальше служить нашему делу.', `QuestCompletionLog` = '' WHERE `ID` = 375 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Так холодно... Чума Нежити расползается по моим венам, как клубок ледяных змей, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне 5 шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, $n, чтобы я могла и дальше служить нашему делу.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
