UPDATE `quest_template_locale` SET `QuestDescription` = 'В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться. $b$bПохоже, и ты будешь $gзаписан:записана; к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.' WHERE `ID` = 376 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться. $b$bПохоже, и ты будешь $gзаписан:записана; к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.' AS BINARY)));
