UPDATE `quest_template_locale` SET `QuestDescription` = 'Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета Альянса. $b$bК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $b$bОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $n.', `QuestCompletionLog` = '' WHERE `ID` = 380 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета Альянса. $b$bК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $b$bОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $n.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
