UPDATE `quest_template_locale` SET `QuestDescription` = 'Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $b$bМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $b$bБудь $gосторожен:осторожна;, нечестивое рвение делает их опасными противниками.', `QuestCompletionLog` = '' WHERE `ID` = 381 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $b$bМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $b$bБудь $gосторожен:осторожна;, нечестивое рвение делает их опасными противниками.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Если б только они послушались доводов разума, а, $n? Может быть, мы могли бы уговорить их все серьезно обсудить... Как же! $b$bИдиоты, ослепленные Светом...' WHERE `ID` = 381 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('Если б только они послушались доводов разума, а, $n? Может быть, мы могли бы уговорить их все серьезно обсудить... Как же! $b$bИдиоты, ослепленные Светом...' AS BINARY)));
