UPDATE `quest_template_locale` SET `QuestDescription` = 'В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из их монастыря к Могильнику. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $b$bА ты, $n, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.' WHERE `ID` = 382 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из их монастыря к Могильнику. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $b$bА ты, $n, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.' AS BINARY)));
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Хмм... Ну-ка, посмотрим, что ты там $gнашел:нашла;... $b$b<Аррен пробегает глазами документы, принесенные вами.> $b$bНовости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... "Продолжайте организацию лагеря около разрушенного города..." Ничего такого, о чем мы не знали бы... А это еще что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать.' WHERE `ID` = 382 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('Хмм... Ну-ка, посмотрим, что ты там $gнашел:нашла;... $b$b<Аррен пробегает глазами документы, принесенные вами.> $b$bНовости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... "Продолжайте организацию лагеря около разрушенного города..." Ничего такого, о чем мы не знали бы... А это еще что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать.' AS BINARY)));
