UPDATE `quest_template_locale` SET `QuestDescription` = 'С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность. Говорят, нельзя вернуться в прошлое – и это верно. Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжен.$b$bЯ спросил у отца о судьбе некоторых моих вещей, например, о моем первом компасе. Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме.$b$bУсадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдешь мой компас?' WHERE `ID` = 399 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность. Говорят, нельзя вернуться в прошлое – и это верно. Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжен.$b$bЯ спросил у отца о судьбе некоторых моих вещей, например, о моем первом компасе. Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме.$b$bУсадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдешь мой компас?' AS BINARY)));
