UPDATE `quest_template_locale` SET `QuestDescription` = 'Если уж у тебя нашлось время передать письмо для Древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Темный Берег, прямо к югу от Аубердина.$b$bТы наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, Древу Мудрости. Он ждет от меня вести, точно так же, как я ждал вести с Поляны Оракула.' WHERE `ID` = 952 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Если уж у тебя нашлось время передать письмо для Древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Темный Берег, прямо к югу от Аубердина.$b$bТы наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, Древу Мудрости. Он ждет от меня вести, точно так же, как я ждал вести с Поляны Оракула.' AS BINARY)));
