UPDATE `quest_template_locale` SET `QuestDescription` = 'Эй, ты! Если ищешь, что бы такого сделать полезного, слушай сюда! $b$bНам нужны свеженькие рекруты, только что из могилы, которых можно направить в Могильник, чтобы они поискали там что-нибудь стоящее из экипировки. Скорее всего, там будут груды ящиков. Мы надеемся, что вскоре поднимутся новые рекруты, а поскольку нам вовсе не надо, чтобы они слонялись тут голыми, надо бы поскорее чем-нибудь поживиться! $b$bА теперь за работу, несчастный ты мешок с костями! Я не собираюсь платить тем, кто еле двигается.', `QuestCompletionLog` = '' WHERE `ID` = 3902 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Эй, ты! Если ищешь, что бы такого сделать полезного, слушай сюда! $b$bНам нужны свеженькие рекруты, только что из могилы, которых можно направить в Могильник, чтобы они поискали там что-нибудь стоящее из экипировки. Скорее всего, там будут груды ящиков. Мы надеемся, что вскоре поднимутся новые рекруты, а поскольку нам вовсе не надо, чтобы они слонялись тут голыми, надо бы поскорее чем-нибудь поживиться! $b$bА теперь за работу, несчастный ты мешок с костями! Я не собираюсь платить тем, кто еле двигается.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
